import React, { useState } from 'react';
import data from './../data/experienceData.js';

function Experience() {
  return (
    <section id="experience" className='py-20 px-6 sm:px-8 lg:px-12'>
      <div className="max-w-6xl mx-auto">
        {/* Clean Section Header */}
        <div className="text-center mb-16">
          <h2 className="text-fluid-4xl font-display font-bold text-gray-900 mb-4">
            Professional <span className="text-accent-color">Experience</span>
          </h2>
          <div className="w-24 h-1 bg-emerald-600 mx-auto rounded-full mb-6"></div>
          <p className="text-muted-light text-fluid-lg max-w-2xl mx-auto leading-relaxed">
            My professional journey through innovative projects and impactful contributions
          </p>
        </div>

        {/* Timeline Experience Cards */}
        <div className="relative">
          {/* Timeline line */}
          <div className="absolute left-8 md:left-1/2 top-0 bottom-0 w-0.5 bg-gray-300 transform md:-translate-x-px"></div>

          <div className="space-y-12">
            {data.map((exp, index) => (
              <ExperienceCard key={exp.id} experience={exp} index={index} />
            ))}
          </div>
        </div>
      </div>
    </section>
  );
}

// Clean Professional Experience Card
function ExperienceCard({ experience, index }) {
  const [isExpanded, setIsExpanded] = useState(false);
  const isEven = index % 2 === 0;

  return (
    <div className="relative flex items-center">
      {/* Timeline dot */}
      <div className="absolute left-8 md:left-1/2 w-4 h-4 bg-emerald-600 border-4 border-white rounded-full transform md:-translate-x-2 z-10 shadow-lg"></div>

      {/* Experience Card */}
      <div className={`w-full md:w-5/12 ${isEven ? 'md:ml-auto md:pl-8' : 'md:pr-8'} ml-20 md:ml-0`}>
        <div className="bg-white rounded-xl p-6 clean-border hover:bg-gray-50 transition-colors duration-200 shadow-md">
          {/* Header */}
          <div className="flex flex-col sm:flex-row sm:items-start sm:justify-between mb-4">
            <div className="flex-1">
              <div className="flex items-center gap-3 mb-2">
                <div className="w-10 h-10 bg-blue-600 rounded-lg flex items-center justify-center">
                  <div className="w-5 h-5 bg-white rounded-sm"></div>
                </div>
                <div>
                  <h3 className="text-fluid-xl font-display font-bold text-white">
                    {experience.title}
                  </h3>
                  <p className="text-accent-color font-semibold">{experience.org}</p>
                </div>
              </div>

              <div className="flex flex-wrap items-center gap-4 text-sm text-muted-light mb-3">
                <span>{experience.date}</span>
                <span>•</span>
                <span>{experience.location}</span>
              </div>
            </div>

            <div className="flex items-center gap-3 mt-3 sm:mt-0">
              <span className={`px-3 py-1 rounded-full text-xs font-medium ${
                experience.type === 'Full-time' 
                  ? 'bg-green-600/20 text-green-400 border border-green-600/30' 
                  : experience.type === 'Internship' 
                  ? 'bg-blue-600/20 text-blue-400 border border-blue-600/30'
                  : 'bg-purple-600/20 text-purple-400 border border-purple-600/30'
              }`}>
                {experience.type}
              </span>

              <button 
                onClick={() => setIsExpanded(!isExpanded)}
                className="flex items-center gap-1 px-3 py-1 bg-blue-600/10 hover:bg-blue-600/20 text-blue-400 rounded-lg text-xs font-medium transition-colors duration-200 clean-border"
              >
                {isExpanded ? 'Less' : 'More'}
                <div className={`w-2 h-2 border-r border-b border-blue-400 transform transition-transform duration-200 ${
                  isExpanded ? '-rotate-135' : 'rotate-45'
                }`}></div>
              </button>
            </div>
          </div>

          {/* Description */}
          <p className="text-gray-300 text-fluid-base font-body leading-relaxed mb-4">
            {experience.description}
          </p>

          {/* Expandable Content */}
          <div className={`overflow-hidden transition-all duration-300 ease-in-out ${
            isExpanded ? 'max-h-96 opacity-100' : 'max-h-0 opacity-0'
          }`}>
            <div className="pt-4 space-y-6">
              {/* Responsibilities */}
              {experience.responsibilities && experience.responsibilities.length > 0 && (
                <div>
                  <h4 className="text-white font-semibold mb-3 text-sm">
                    Key Responsibilities
                  </h4>
                  <ul className="space-y-2">
                    {experience.responsibilities.map((resp, idx) => (
                      <li key={idx} className="text-sm text-gray-300">
                        {resp}
                      </li>
                    ))}
                  </ul>
                </div>
              )}

              {/* Achievements */}
              {experience.achievements && experience.achievements.length > 0 && (
                <div>
                  <h4 className="text-white font-semibold mb-3 text-sm">
                    Key Achievements
                  </h4>
                  <ul className="space-y-2">
                    {experience.achievements.map((achievement, idx) => (
                      <li key={idx} className="text-sm text-gray-300">
                        {achievement}
                      </li>
                    ))}
                  </ul>
                </div>
              )}
            </div>
          </div>

          {/* Technologies */}
          {experience.technologies && experience.technologies.length > 0 && (
            <div className="mt-4 pt-4 border-t border-gray-700">
              <div className="flex flex-wrap gap-2">
                {experience.technologies.map((tech, idx) => (
                  <span 
                    key={idx} 
                    className="px-3 py-1 bg-slate-700/50 text-gray-300 rounded-lg text-xs font-medium clean-border"
                  >
                    {tech}
                  </span>
                ))}
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

export default Experience;
